package com.stockshield.controller;
import com.stockshield.dto.*; import com.stockshield.entity.*; import com.stockshield.service.*; import jakarta.validation.Valid; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import java.util.*;
@RestController @RequestMapping("/api") public class ApiController {private final ProductService ps;private final OrderService os;private final SimulationService ss;private final EventPublisher ep;public ApiController(ProductService p,OrderService o,SimulationService s,EventPublisher e){ps=p;os=o;ss=s;ep=e;}
@GetMapping("/products") public List<Product> products(){return ps.all();}@PostMapping("/products") public Product create(@Valid @RequestBody CreateProductRequest r){return ps.create(r);}@PutMapping("/products/{id}/inventory") public Product reset(@PathVariable Long id,@RequestParam int quantity){return ps.reset(id,quantity);}
@PostMapping("/orders") public Order order(@Valid @RequestBody OrderRequest r){return os.createAndSubmit(r.productId(),r.quantity(),r.idempotencyKey());}@GetMapping("/orders") public List<Order> orders(){return os.recent();}@GetMapping("/orders/events") public List<OrderEvent> events(){return os.recent().stream().flatMap(o->java.util.stream.Stream.empty()).toList();}
@GetMapping(value="/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter stream(){return ep.subscribe();}@GetMapping("/dlq") public List<DeadLetterOrder> dlq(){return os.deadLetters();}@PostMapping("/dlq/{id}/reprocess") public void reprocess(@PathVariable Long id){os.reprocessDlq(id);}@PostMapping("/simulate") public Map<String,Object> simulate(@Valid @RequestBody SimulationRequest r){return ss.run(r);}
@GetMapping("/stats") public Map<String,Object> stats(){return new LinkedHashMap<>(Map.of("totalOrders",os.recent().size(),"processing",os.count(Order.Status.PROCESSING),"success",os.count(Order.Status.SUCCESS),"failed",os.count(Order.Status.FAILED),"retrying",os.count(Order.Status.RETRYING),"outOfStock",os.count(Order.Status.OUT_OF_STOCK),"dlq",os.count(Order.Status.DLQ)));}}
